using System;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "OnPlayerSixCorruptionOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/OnPlayerSixCorruptionOmenData")]
public class OnPlayerSixCorruptionOmenData : OmenData
{
	[NonSerialized]
	private Action omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = OmenAction(omenInstance);
		ReferenceSingleton<MiscOmensHandler>.Instance.OnPlayerSixCorruptionOmenAction.Add(omenAction);
	}

	private Action OmenAction(OmenInstance omenInstance)
	{
		return delegate
		{
			ActivateOmen();
			omenInstance.ActivateOmenFeedback();
		};
	}

	public override void OmenRemoved()
	{
		base.OmenRemoved();
		ReferenceSingleton<MiscOmensHandler>.Instance.OnPlayerSixCorruptionOmenAction.Remove(omenAction);
	}

	protected override string GetOmenRawLocalizedDescription()
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("DeepnessPresence_DCorruptionMeter");
	}
}
